// Android-only helpers: read posted notifications and permission state through adb (no Appium driver needed).
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

const devFile = path.join(os.homedir(), '.qa-tester', 'devices.json');
const dev = fs.existsSync(devFile) ? JSON.parse(fs.readFileSync(devFile, 'utf8')) : {};
const ADB = process.env.ANDROID_HOME ? path.join(process.env.ANDROID_HOME, 'platform-tools', 'adb') : 'adb';
const UDID = process.env.ANDROID_UDID || dev.android?.udid;

export function adb(...args) {
  const a = UDID ? ['-s', UDID, ...args] : args;
  return execFileSync(ADB, a, { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 });
}

const field = (block, key) => {
  const m = block.match(new RegExp(`\\b${key.replace('.', '\\.')}=\\S+ \\((.*)\\)`));
  return m ? m[1] : null;
};

/** Notifications currently posted by `pkg`: [{ key, title, text }] from `dumpsys notification --noredact`. */
export function listNotifications(pkg) {
  const out = adb('shell', 'dumpsys', 'notification', '--noredact');
  return out.split('NotificationRecord(').slice(1)
    .filter((b) => b.includes(`pkg=${pkg} `))
    .map((b) => ({ key: (b.match(/key=(\S+)/) || [])[1] || null, title: field(b, 'android.title'), text: field(b, 'android.text') }));
}

/** Wait until a notification of `pkg` whose text contains `text` is posted. Polls adb; returns the record. */
export async function waitForNotification(pkg, text, { timeout = 60000, interval = 2000 } = {}) {
  const end = Date.now() + timeout;
  for (;;) {
    const hit = listNotifications(pkg).find((n) => n.text && n.text.includes(text));
    if (hit) return hit;
    if (Date.now() > end) throw new Error(`no notification from ${pkg} with text "${text}" within ${timeout} ms`);
    await new Promise((r) => setTimeout(r, interval));
  }
}

/** true when the runtime permission POST_NOTIFICATIONS (Android 13+) is granted to `pkg`. */
export function notificationPermissionGranted(pkg) {
  const out = adb('shell', 'dumpsys', 'package', pkg);
  return /android\.permission\.POST_NOTIFICATIONS: granted=true/.test(out);
}

/** Kill the app process like swiping it away from recents (NOT force-stop, which blocks FCM delivery). App must be in background. */
export function killInBackground(pkg) { adb('shell', 'am', 'kill', pkg); }

export function processRunning(pkg) {
  try { return adb('shell', 'pidof', pkg).trim().length > 0; } catch { return false; }
}
